// D14 企业问AI代理 · 从企业主壳的「问AI代理」横幅进入。
// 同构镜像求职端 A27 问AI代理：结构与像素值一致，只换数据源与文案视角。
//
// 屏幕结构（自上而下）：
//   返回栏（标题 + 右侧 ⋯）→ 对话流（Mock 第一条是今日简报卡）→ 快捷问句胶囊行 → 真输入条
//   （Backend 的输入条是禁用外壳：值恒为空、占位交代暂未开放，不可发送）
//
// 与求职端的差异只有两处：
//   · 简报卡在统计条下方多一块「人才漏斗」：五档横条（宽度=数据宽度%，橄榄渐变到淡绿），
//     只有「硬性匹配」可点（容器在下面把动作与读屏说明挂上去）
//   · 关键词回复规则表换成招聘方口径（漏斗 / 触达 / 带宽 / A-01 到岗）
// 简报卡本体（含建议卡落点理由）在 组件/问AI代理/简报展示。
//
// 模式分支（真话批次交付 G，镜像求职端）：默认导出在任何 Mock state/effect 挂载前同步分流 ——
//   · Backend：不初始化 fixture 会话、不渲染简报/漏斗/对话/快捷问句、不排定时回复、
//     不派发 Mock 规则 mutation。代理气泡只交代真实去处（推荐 / 在谈 / AI 代理设置），
//     快捷行的三个既有槽位换成真实导航按钮；右侧 ⋯ 仍是既有的代理详情入口。
//   · Mock：原型原样保留 —— 今日简报、人才漏斗、快捷问句、真输入、关键词回复一个不少；
//     回复定时器由 Mock 体自己持有，卸载 / 切数据源时全部取消，
//     排队中的假回复不可能活到 Backend 分支。
// 网络失败、登出、首次水合、数据源切换都不会把 Backend 落回 Mock 分支。

import { useEffect, useRef, useState } from 'react';
import 样式 from './企业问AI代理.module.css';
import { 次级页外壳, 返回栏, 真输入条 } from '../组件/通用';
import { 代理气泡, 我方气泡, 快捷操作行 } from '../组件/问AI代理/对话展示';
import { 简报展示 } from '../组件/问AI代理/简报展示';
import type { 漏斗展示档 } from '../组件/问AI代理/简报展示';
import { use导航 } from '../路由/导航钩子';
import { 路径 } from '../路由/路径表';
import { use应用状态 } from '../状态/应用状态';
import { 人才漏斗, 企业日报, 企业代理对话初始, 企业快捷问句 } from '../数据/企业端模拟数据';
import type { 代理对话条 } from '../数据/类型';

// 漏斗里唯一可点的一档：点「硬性匹配」进本周初筛记录，看代理这一周按哪几条硬性筛的、
// 挡掉的是谁。其余四档本轮还没有对应的落地屏，保持不可点（不做假入口）。
const 可点漏斗档 = '硬性匹配';

// 关键词 → mock 回复（招聘方口径）。原型不接后端，用规则表模拟代理应答；
// 顺序即优先级：先命中的先返回，最后一条是兜底。
// 双盲约束：回复里只出现匿名昵称（陈屿 / 江叙白），绝不出现真名；薪资只答「有无交集」，不给数值。
function 生成回复(问题: string): string {
  if (问题.includes('漏斗') || 问题.includes('进展'))
    return '本周漏斗：触达 23 → 硬性匹配 12 → 在谈 5 → 深谈 2 → 意向达成 1。转化卡在硬性匹配这档，主栈放宽半档能多进 4 人，要不要试两周？';
  if (问题.includes('触达') || 问题.includes('再找'))
    return '好，按现有硬性五项再去触达 10 个对口的，两天内给你首批画像。硬性不符的我直接挡掉，不拿来烦你。';
  if (问题.includes('带宽') || 问题.includes('薪资'))
    return '带宽内有交集的还有 3 位：江叙白 / 周砚秋 / 许临风。按双盲规矩我只核「有无交集」，拿不到对方数值，也不会把咱们的带外余量透出去。';
  if (问题.includes('陈屿') || 问题.includes('到岗'))
    return '对方代理明确 45 天到岗是硬线（现职交接），其余条件全部一致。匹配分 94 半年内只出现过 2 次，我的建议是接受，等你拍板。';
  return '收到。我按这个口径继续筛、继续谈；碰到规则之外的卡点会先来问你，不会替你拍板。';
}

export default function 企业问AI代理() {
  const { 数据源模式 } = use应用状态();
  return 数据源模式 === 'backend' ? <Backend企业问AI代理 /> : <Mock企业问AI代理 />;
}

// ── Backend：只读的真实导航壳。复用既有外壳 / 返回栏 / 代理气泡 / 快捷槽，不建新结构 ──
function Backend企业问AI代理() {
  const { 返回, 跳转, 替换跳转 } = use导航();
  const { 派发 } = use应用状态();

  // 两个主壳快捷键共用：先摆好目标 Tab + 子视图状态，再原地替换进企业主壳 ——
  // 与求职端 问AI代理 的 去主壳 同一套动作，用户落进主壳看到的就是选好的那个视图。
  const 去主壳 = (子视图: '推荐' | '在谈') => {
    派发({ 型: '企业切Tab', Tab: '人才' });
    派发({ 型: '企业切子视图', 子视图 });
    替换跳转(路径.企业主壳);
  };

  return (
    <次级页外壳 对话底 白底>
      <返回栏
        返回={返回}
        标题="我的招聘AI代理"
        右侧={<button className={`${样式.更多} 可点`} onClick={() => 跳转(路径.企业代理详情)}>⋯</button>}
      />

      <div className={`${样式.对话流} 滚动区`}>
        <div className={样式.对话内容}>
          <代理气泡 外观="招聘" 内容="真实匹配与委托请从「推荐」进入，真实阶段请到「在谈」查看，长期规则请到「AI 代理设置」提交。当前 Backend 模式暂不提供自由对话、日报和漏斗。" />
        </div>
      </div>

      <快捷操作行
        外观="招聘"
        项们={[
          { 键: '看推荐', 文案: '看推荐', 按下: () => 去主壳('推荐') },
          { 键: '看在谈', 文案: '看在谈', 按下: () => 去主壳('在谈') },
          { 键: 'AI代理设置', 文案: 'AI代理设置', 按下: () => 跳转(路径.企业代理设置) },
        ]}
      />

      {/* Backend 外壳：完整但不可发送 —— 值恒为空、占位交代暂未开放，
          textarea 与发送键走 真输入条 既有的真 disabled（键盘路径一并挡掉）；
          改变/发送是无副作用回调，不依赖也不触碰 Mock 发送。 */}
      <真输入条 占位="AI代理聊天暂未开放" 值="" 改变={() => {}} 发送={() => {}} 禁用 />
    </次级页外壳>
  );
}

// ── Mock：原型对话体，只在 mock 模式挂载 ──
function Mock企业问AI代理() {
  const { 返回, 跳转 } = use导航();
  const { 状态, 派发 } = use应用状态();

  // 「放宽薪资带」= 把这条放宽写成一条真规则，再跳AI代理设置让招聘方当场看到结果。
  // 这套动作原本长在已删除的 候选未通过 屏上，逻辑一行未改，只是换了触发它的地方。
  // 本体只在 mock 模式挂载（模式门在 state/effect 之前分流），Backend 结构上碰不到这里；
  // 写规则归 企业代理设置（canonical），落规则后当场跳过去看到结果。
  const 放宽薪资带 = () => {
    派发({
      型: '企业新增规则',
      内容: 企业日报.松一档.规则内容,
      来源: 企业日报.松一档.规则来源,
    });
    跳转(路径.企业代理设置);
  };

  // 「维持红线」不改任何规则，只把这条建议标记为已处理，避免点了没反应。
  // 处理状态在 Mock 容器（展示件不自持）：父级把确认文案经 建议.处理文案 送进卡片，
  // 没送之前组件不得自行换成「已维持」。
  const [已维持红线, 设已维持红线] = useState(false);

  // 漏斗展示数据：人数/宽度原样取 fixture（不从人数推算宽度）；
  // 只有「硬性匹配」那一档挂动作（本屏唯一真实入口），其余四档没有落地屏，保持不可点。
  const 漏斗展示: 漏斗展示档[] = 人才漏斗.map((档) => ({
    名称: 档.名称,
    人数: 档.人数,
    宽度: 档.宽度,
    动作:
      档.名称 === 可点漏斗档
        ? {
            // 行内可见的只有档名和人数，读屏说明由容器补上落到哪一屏（原 aria-label 原样保留）
            说明: `${档.名称} ${档.人数}，打开本周初筛记录`,
            按下: () => 跳转(路径.初筛记录),
          }
        : null,
  }));

  const [对话, 设对话] = useState<代理对话条[]>(企业代理对话初始);
  const [草稿, 设草稿] = useState('');
  // 对话流容器：需要拿原生 DOM 节点手动滚到底，所以用 div.滚动区 而不是 <滚动区> 组件
  const 滚动引用 = useRef<HTMLDivElement>(null);
  // 550ms 假回复的定时器句柄集合：卸载（含切到 Backend 分支）时统一取消，
  // 不让一条排队的模拟回复在别的模式 / 别的页面上凭空冒出来。
  const 回复定时器 = useRef<Set<number>>(new Set());

  useEffect(() => () => {
    回复定时器.current.forEach((handle) => window.clearTimeout(handle));
    回复定时器.current.clear();
  }, []);

  // 对话每变一次就滚到底部（含代理 550ms 后追加的那条），保证新消息始终可见
  useEffect(() => {
    const 容器 = 滚动引用.current;
    if (!容器) return;
    容器.scrollTo({ top: 容器.scrollHeight, behavior: 'smooth' });
  }, [对话]);

  // 发送：不带参数发草稿（输入框），带参数发快捷问句
  const 发送 = (文本?: string) => {
    const 内容 = (文本 ?? 草稿).trim();
    if (!内容) return;
    // 用时刻做编号：我方那条用 时刻，代理回复用 时刻+1，保证两条 key 不撞
    const 时刻 = Date.now();
    设对话((旧) => [...旧, { 编号: 时刻, 角色: '我', 内容 }]);
    设草稿('');
    const handle = window.setTimeout(() => {
      回复定时器.current.delete(handle);
      设对话((旧) => [...旧, { 编号: 时刻 + 1, 角色: '代理', 内容: 生成回复(内容) }]);
    }, 550);
    回复定时器.current.add(handle);
  };

  return (
    <次级页外壳 对话底 白底> {/* 2026-08-24 全站去框（产品负责人批）：页底转纯白，与私聊三屏一致 */}
      <返回栏 返回={返回} 标题="我的招聘AI代理" 右侧={<button className={`${样式.更多} 可点`} onClick={() => 跳转(路径.企业代理详情)}>⋯</button>} />

      {/* 对话流：屏幕内唯一滚动区 */}
      <div ref={滚动引用} className={`${样式.对话流} 滚动区`}>
        <div className={样式.对话内容}>
          {对话.map((条) => {
            if (条.角色 === '简报')
              return (
                <简报展示
                  key={条.编号}
                  外观="招聘"
                  标题="今日简报"
                  更新时间="09:00 更新"
                  统计={企业日报.统计}
                  正文前={企业日报.正文前}
                  正文强调={企业日报.正文强调}
                  正文后={企业日报.正文后}
                  脚注={企业日报.脚注}
                  漏斗={漏斗展示}
                  建议={{
                    标题: 企业日报.松一档.标题,
                    正文前: 企业日报.松一档.正文前,
                    数值1: 企业日报.松一档.数值1,
                    正文中: 企业日报.松一档.正文中,
                    数值2: 企业日报.松一档.数值2,
                    正文后: 企业日报.松一档.正文后,
                    维持文案: '维持红线',
                    放宽文案: '放宽薪资带',
                    处理文案: 已维持红线
                      ? '已维持红线 · 规则不变，我会继续替你挡掉这类候选。'
                      : null,
                    维持: () => 设已维持红线(true),
                    放宽: 放宽薪资带,
                  }}
                />
              );
            if (条.角色 === '我')
              return (
                <我方气泡
                  key={条.编号}
                  外观="招聘"
                  内容={条.内容 ?? ''}
                  头像URL={状态.招聘头像}
                  首字={状态.企业认证.姓名.charAt(0)}
                />
              );
            return <代理气泡 key={条.编号} 外观="招聘" 内容={条.内容 ?? ''} />;
          })}
        </div>
      </div>

      {/* 快捷问句：点一下等于直接把这句话发出去 */}
      <快捷操作行
        外观="招聘"
        项们={企业快捷问句.map((句) => ({ 键: 句, 文案: 句, 按下: () => 发送(句) }))}
      />

      <真输入条
        占位="让AI代理找人、触达，或问漏斗…"
        值={草稿}
        改变={设草稿}
        发送={() => 发送()}
      />
    </次级页外壳>
  );
}
